head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};


	scwin.btn_menuOpen_onclick = function(e) {
		var menuId = "A00001";
		var menuNm = "업무화면1";
		var menuUrl = "tabControl_processMsgFrame_WESD-970_(WSQ-4939)_sub1.xml";		

		var tabObj = { 
			closable		: true,	
			openAction	: "exist",	
			label			: menuNm 
		};

		var contObj = {
			frameMode	: "wframePreload",
			scope			: true,
			src			: menuUrl,
			alwaysDraw	: false,
			title			: menuNm,
			dataObject : { 
				type	: "json", 
				name	: "param", 
				data	: {}
			}
		};

		//content 탭 생성 (생성 탭에 포커스는 별도)  
		var result = tac_layout.addTab(menuId, tabObj, contObj);

		//동일 menuId 의 화면을 new로 생성 할수 있기에, 생성된 tab select 처리 필요함
		//var tabIndex = tac_layout.getTabIndex( result );
		//tac_layout.setSelectedTabIndex( tabIndex );		
	};


	scwin.checkVal = function() {
		//console.log("log1 : "+localStorage.getItem('log1')+ " : log2 : "+ localStorage.getItem('log2'));
		return localStorage.getItem('log1') <= localStorage.getItem('log2');
	}
	function unitTest(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_menuOpen').click()");
		WebSquare.wUnit.addCommand("pause", "400");			
        WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	unitTest();	
	localStorage.removeItem("log1");	
	localStorage.removeItem("log2");
